import numpy as np
import random

def get_max_k(N, s, iterations=10000):
    max_k = 0
    for _ in range(iterations):
        # Randomly choose weights w_xy
        w = np.random.randint(0, 3, (N - s + 1, N - s + 1))
        C = np.zeros((N, N), dtype=int)
        for x in range(N - s + 1):
            for y in range(N - s + 1):
                if w[x, y] > 0:
                    C[x:x+s, y:y+s] += w[x, y]

        unique_vals, counts = np.unique(C, return_counts=True)
        for val, count in zip(unique_vals, counts):
            if val > 0:
                max_k = max(max_k, count)
    return max_k

