import numpy as np

def get_k(w, N, s):
    C = np.zeros((N, N), dtype=int)
    for x in range(N - s + 1):
        for y in range(N - s + 1):
            if w[x, y] > 0:
                C[x:x+s, y:y+s] += w[x, y]
    unique_vals, counts = np.unique(C, return_counts=True)
    max_count = 0
    for val, count in zip(unique_vals, counts):
        if val > 0:
            max_count = max(max_count, count)
    return max_count

def hill_climbing(N, s):
    w = np.random.randint(0, 2, (N - s + 1, N - s + 1))
    current_k = get_k(w, N, s)

    while True:
        improved = False
        for x in range(N - s + 1):
            for y in range(N - s + 1):
                old_val = w[x, y]
                for new_val in [0, 1, 2]:
                    if new_val == old_val: continue
                    w[x, y] = new_val
                    new_k = get_k(w, N, s)
                    if new_k > current_k:
                        current_k = new_k
                        improved = True
                        break
                    else:
                        w[x, y] = old_val
                if improved: break
            if improved: break
        if not improved:
            break
    return current_k

for N in [3, 4, 5]:
    best_k = 0
    for _ in range(20):
        best_k = max(best_k, hill_climbing(N, 2))
    print(f"N={N}, s=2: {best_k}")

