import numpy as np
import itertools

def get_k(w, N, s):
    C = np.zeros((N, N), dtype=int)
    for x in range(N - s + 1):
        for y in range(N - s + 1):
            if w[x, y] > 0:
                C[x:x+s, y:y+s] += w[x, y]
    unique_vals, counts = np.unique(C, return_counts=True)
    max_count = 0
    for val, count in zip(unique_vals, counts):
        if val > 0:
            max_count = max(max_count, count)
    return max_count

def solve_exhaustive(N, s):
    best_k = 0
    num_pos = (N - s + 1) ** 2
    for w_flat in itertools.product(range(3), repeat=num_pos):
        w = np.array(w_flat).reshape((N - s + 1, N - s + 1))
        best_k = max(best_k, get_k(w, N, s))
    return best_k

